{
  "slug": "dormant-guest-accounts",
  "description": "Loads guest users from Microsoft Graph and summarizes dormant ones using an LLM step.",
  "steps": [
    {
      "name": "fetch_guest_users",
      "type": "graph",
      "config": {
        "endpoint": "microsoft_graph",
        "query": "users?$filter=type eq 'Guest'&$select=id,displayName,accountEnabled",
        "auth": "aad"
      }
    },
    {
      "name": "filter_dormant_users",
      "type": "filter",
      "config": {
        "condition": "accountEnabled eq false"
      }
    },
    {
      "name": "summarize_dormant",
      "type": "llm",
      "config": {
        "prompt": "Summarize the following list of dormant guest accounts: {{ input }}",
        "model": "gpt-4"
      }
    }
  ]
}
